_CORE_SRC = '# Action: "{from_node: {to_node: count, ...}}".\n# "capacity_p = serving_p * UNIT_CAPACITY", serving_p = min(units_p, 6).\n# "filled_p = capacity_p * orders / max(total_capacity, orders)".\n# Away from home, each unit costs "1.0 + 0.5 * hops(your_base, node)";\n# at home it costs zero. Moves precede payout; only start-of-turn units move.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 90\n\n\ndef preprocess_map(graph):\n    n = int(graph["nodes"])\n    adj = [[] for _ in range(n)]\n    for u, v in graph["links"]:\n        adj[u].append(v)\n        adj[v].append(u)\n    for row in adj:\n        row.sort()\n    dist = []\n    for s in range(n):\n        d = [n + 1] * n\n        d[s] = 0\n        q = deque([s])\n        while q:\n            u = q.popleft()\n            for v in adj[u]:\n                if d[v] > d[u] + 1:\n                    d[v] = d[u] + 1\n                    q.append(v)\n        dist.append(d)\n    hop = [[s] * n for s in range(n)]\n    for s in range(n):\n        for t in range(n):\n            if s != t:\n                hop[s][t] = min(\n                    (v for v in adj[s] if dist[v][t] == dist[s][t] - 1),\n                    default=s,\n                )\n    return adj, dist, hop\n\n\ndef filled(a, b, demand):\n    ca = 4 * min(a, 6)\n    cb = 4 * min(b, 6)\n    denominator = max(ca + cb, demand)\n    return ca * demand / denominator if denominator > 0 else 0.0\n\n\ndef profits(a, b, demand, costs_a, costs_b):\n    pa = pb = 0.0\n    for i, d in enumerate(demand):\n        pa += filled(a[i], b[i], d) - costs_a[i] * a[i]\n        pb += filled(b[i], a[i], d) - costs_b[i] * b[i]\n    return pa, pb\n\n\ndef apply_moves(units, action, adj):\n    """Exact start-of-turn movement availability and sequential rejection."""\n    result = list(units)\n    available = list(units)\n    n = len(units)\n    if type(action) is not dict:\n        return result\n    for s, row in action.items():\n        if type(s) is not int or type(row) is not dict:\n            return list(units)\n        for t, k in row.items():\n            if type(t) is not int or type(k) is not int:\n                return list(units)\n    for s, row in action.items():\n        for t, k in row.items():\n            if (0 <= s < n and 0 <= t < n and t in adj[s]\n                    and 0 <= k <= available[s]):\n                available[s] -= k\n                result[s] -= k\n                result[t] += k\n    return result\n\n\ndef simulate_turn(state, my_action, opponent_action):\n    """Pure transition: positions, forecast offset, immutable game data."""\n    a, b, offset, forecast, ca, cb, adj = state\n    na = apply_moves(a, my_action, adj)\n    nb = apply_moves(b, opponent_action, adj)\n    demand = forecast[min(offset, len(forecast) - 1)]\n    ga, gb = profits(na, nb, demand, ca, cb)\n    return (na, nb, offset + 1, forecast, ca, cb, adj), ga, gb\n\n\ndef plan_to_action(have, target, dist, hop, adj):\n    """Pair surplus with closest deficits, then validate every emitted move."""\n    n = len(have)\n    surplus = [max(0, have[i] - target[i]) for i in range(n)]\n    deficit = [max(0, target[i] - have[i]) for i in range(n)]\n    pairs = sorted(\n        (dist[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and s != t\n    )\n    proposed = {}\n    for _, s, t in pairs:\n        k = min(surplus[s], deficit[t])\n        if k:\n            v = hop[s][t]\n            if v != s:\n                proposed.setdefault(s, {})[v] = proposed.get(s, {}).get(v, 0) + k\n                surplus[s] -= k\n                deficit[t] -= k\n    available = list(have)\n    action = {}\n    for s in sorted(proposed):\n        for t in sorted(proposed[s]):\n            k = min(proposed[s][t], available[s])\n            if k > 0 and t in adj[s] and t != s:\n                action.setdefault(int(s), {})[int(t)] = int(k)\n                available[s] -= k\n    return action\n\n\ndef allocation(have, enemy, base, costs, demand, dist, horizon, denial,\n               travel_weight, deadline):\n    """Concave marginal allocation with a travel/payback penalty."""\n    n = len(have)\n    want = [0] * n\n    remaining = list(have)\n    for _ in range(sum(have)):\n        if time.perf_counter() >= deadline:\n            break\n        best = 0.03\n        choice = None\n        for t in range(n):\n            if t == base or want[t] >= 6:\n                continue\n            k = want[t]\n            gain = (filled(k + 1, enemy[t], demand[t])\n                    - filled(k, enemy[t], demand[t])\n                    + denial * (filled(enemy[t], k, demand[t])\n                                - filled(enemy[t], k + 1, demand[t]))\n                    - costs[t])\n            if gain <= 0:\n                continue\n            for s in range(n):\n                if not remaining[s]:\n                    continue\n                distance = dist[s][t]\n                delay = max(0, distance - 1)\n                productive = max(0.0, horizon - delay)\n                # Includes deployment upkeep during travel and lost opportunity\n                # from pulling an already productive unit off its present node.\n                transit = delay * (costs[s] + costs[t]) * 0.5\n                value = (productive * gain - travel_weight *\n                         (transit + 0.65 * distance))\n                if value > best:\n                    best = value\n                    choice = (s, t)\n        if choice is None:\n            break\n        s, t = choice\n        remaining[s] -= 1\n        want[t] += 1\n    want[base] += sum(remaining)\n    return want\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous = None\n        self.bad_reports = 0\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0001, 0.58 * TIME_BUDGET)\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs["graph"])\n        adj, dist, hop = self.map_data\n        a = list(obs["you"]["units"])\n        b = list(obs["rival"]["units"])\n        n = len(a)\n        home = int(obs["you"]["base"])\n        enemy_home = int(obs["rival"]["base"])\n        turn = int(obs.get("turn", 0))\n        left = max(1, N_TURNS - turn)\n        forecast = obs.get("orders", [])\n        if not forecast:\n            return {}\n        ca = [0.0 if i == home else 1.0 + 0.5 * dist[home][i]\n              for i in range(n)]\n        cb = [0.0 if i == enemy_home else 1.0 + 0.5 * dist[enemy_home][i]\n              for i in range(n)]\n        feedback = obs.get("feedback", {})\n        if not feedback.get("format_ok", True) or feedback.get("rejected", 0):\n            self.bad_reports += 1\n\n        demand = [\n            sum(row[i] * w for row, w in\n                zip(forecast, (0.45, 0.33, 0.22))) /\n            sum((0.45, 0.33, 0.22)[:len(forecast)])\n            for i in range(n)\n        ]\n        default = allocation(a, b, home, ca, demand, dist, min(left, 7),\n                             1.0, 1.0, deadline)\n        best_target = default\n        answer = plan_to_action(a, default, dist, hop, adj)\n        if self.bad_reports >= 2 or time.perf_counter() >= deadline:\n            self.previous = list(default)\n            return answer\n\n        candidates = [default, list(a)]\n        if self.previous is not None and len(self.previous) == n:\n            candidates.append(list(self.previous))\n        retreat = list(a)\n        for i in range(n):\n            if i != home and (a[i] > 6 or\n                    filled(a[i], b[i], demand[i]) < ca[i] * a[i]):\n                retreat[home] += retreat[i]\n                retreat[i] = 0\n        candidates.append(retreat)\n        for horizon, denial, travel in (\n                (4, 1.0, 1.0), (10, 1.0, 1.0),\n                (7, 0.0, 1.0), (7, 1.5, 0.8),\n                (12, 0.7, 1.4)):\n            if time.perf_counter() >= deadline:\n                break\n            candidates.append(allocation(\n                a, b, home, ca, demand, dist, min(left, horizon),\n                denial, travel, deadline))\n\n        opponents = [list(b)]\n        for denial in (0.0, 1.0):\n            if time.perf_counter() >= deadline:\n                break\n            opponents.append(allocation(\n                b, a, enemy_home, cb, demand, dist, min(left, 7),\n                denial, 1.0, deadline))\n\n        best_value = float("-inf")\n        seen = set()\n        for target in candidates:\n            key = tuple(target)\n            if key in seen:\n                continue\n            seen.add(key)\n            values = []\n            complete = True\n            for enemy_target in opponents:\n                state = (a, b, 0, forecast, ca, cb, adj)\n                total = 0.0\n                depth = min(left, 7)\n                for step in range(depth):\n                    if time.perf_counter() >= deadline:\n                        complete = False\n                        break\n                    ma = plan_to_action(state[0], target, dist, hop, adj)\n                    mb = plan_to_action(state[1], enemy_target, dist, hop, adj)\n                    state, ga, gb = simulate_turn(state, ma, mb)\n                    total += (ga - gb) * (0.96 ** step)\n                if not complete:\n                    break\n                if left > depth:\n                    ga, gb = profits(state[0], state[1], forecast[-1], ca, cb)\n                    total += min(2, left - depth) * (ga - gb) * 0.75\n                values.append(total)\n            if not complete:\n                break\n            if values:\n                mean = sum(values) / len(values)\n                value = 0.85 * mean + 0.15 * min(values)\n                if value > best_value + 0.015:\n                    best_value = value\n                    best_target = target\n                    answer = plan_to_action(a, target, dist, hop, adj)\n        self.previous = list(best_target)\n        return answer\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = '# Exact action format: {from_node: {to_node: count, ...}, ...}\n# Payout: serving_p = min(units_p at the node, SERVE_LIMIT);\n# capacity_p = serving_p * UNIT_CAPACITY;\n# filled_p = capacity_p * orders / max(total_capacity, orders).\n# Cost: every unit away from its own base pays\n# 1.0 + 0.5 * hops(own_base, node) each turn; units at home cost 0.\n# Moves precede payout. This conservative fallback deploys only one hop from\n# home: deployment earns immediately, and returning home has no upkeep cost.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 90\nUNIT_CAPACITY = 4\nSERVE_LIMIT = 6\nSAFETY_MARGIN = 0.20\n\n\ndef preprocess_map(graph):\n    """Static, deterministic graph data; no assumptions about example node ids."""\n    n = int(graph["nodes"])\n    adjacency = [[] for _ in range(n)]\n    for u, v in graph["links"]:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for row in adjacency:\n        row.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if distance[v] == -1:\n                    distance[v] = distance[u] + 1\n                    queue.append(v)\n        distances.append(distance)\n    return adjacency, distances\n\n\ndef filled_orders(own_units, rival_units, orders):\n    """The specification\'s revenue formula, including the serving cap."""\n    own_capacity = min(own_units, SERVE_LIMIT) * UNIT_CAPACITY\n    rival_capacity = min(rival_units, SERVE_LIMIT) * UNIT_CAPACITY\n    denominator = max(own_capacity + rival_capacity, orders)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * orders / denominator\n\n\ndef plan_nearby(obs, adjacency, conservative):\n    """Allocate only to immediately reachable, clearly profitable work.\n\n    Adjacent nodes have no unpaid outbound travel turn. Their exact return\n    cost is zero, since a single move reaches home before the next payout.\n    Keeping spare units home also prevents speculative deployment costs.\n    """\n    base = int(obs["you"]["base"])\n    have = obs["you"]["units"]\n    rival = obs["rival"]["units"]\n    turn = int(obs.get("turn", 0))\n    rows = obs.get("orders", [])[:max(0, N_TURNS - turn)]\n    desired = {v: 0 for v in adjacency[base]}\n    if not rows:\n        return desired\n\n    # After repeated feedback errors, limit the forecast-dependent portion\n    # further, while keeping exactly the same simple, checked movement rule.\n    forecasts = rows[:1] if conservative else rows[:3]\n    remaining = sum(have)\n\n    # At most 6 serving slots per neighbor, each with decreasing marginal\n    # revenue. Reject the first unprofitable slot and all subsequent ones.\n    candidates = []\n    for v in adjacency[base]:\n        for count in range(SERVE_LIMIT):\n            worst_gain = min(\n                filled_orders(count + 1, rival[v], row[v])\n                - filled_orders(count, rival[v], row[v])\n                for row in forecasts\n            )\n            net = worst_gain - 1.5\n            if net <= SAFETY_MARGIN:\n                break\n            # Prefer already placed units when economically tied.\n            candidates.append((-net, 0 if count < have[v] else 1, v, count))\n\n    candidates.sort()\n    for _, _, v, count in candidates:\n        if remaining <= 0:\n            break\n        if count == desired[v]:\n            desired[v] += 1\n            remaining -= 1\n    return desired\n\n\ndef legal_action(plan, have, adjacency):\n    """Validate each proposed move against unmodified start-of-turn supplies."""\n    available = [int(value) for value in have]\n    n = len(available)\n    action = {}\n    for source, destination, requested in plan:\n        source = int(source)\n        destination = int(destination)\n        requested = int(requested)\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if destination not in adjacency[source]:\n            continue\n        count = min(max(0, requested), available[source])\n        if count <= 0:\n            continue\n        available[source] -= count\n        inner = action.setdefault(int(source), {})\n        inner[int(destination)] = int(inner.get(destination, 0) + count)\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_data = None\n        self.bad_reports = 0\n\n    def act(self, obs):\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs["graph"])\n        adjacency, distances = self.map_data\n\n        feedback = obs.get("feedback", {})\n        if (feedback.get("format_ok", True) is False\n                or feedback.get("rejected", 0) > 0):\n            self.bad_reports += 1\n\n        have = obs["you"]["units"]\n        base = int(obs["you"]["base"])\n        desired = plan_nearby(obs, adjacency, self.bad_reports >= 2)\n        plan = []\n\n        # Retain profitable local workers and recall all local surplus directly.\n        for source in range(len(have)):\n            if source == base or have[source] <= 0:\n                continue\n            if source in desired:\n                surplus = int(have[source]) - desired[source]\n                if surplus > 0:\n                    plan.append((source, base, surplus))\n            else:\n                # Normally unreachable under this strategy\'s own actions.\n                # If first called with remote workers, safely retreat them\n                # rather than assuming any previous internal plan.\n                nearer = [\n                    v for v in adjacency[source]\n                    if distances[v][base] == distances[source][base] - 1\n                ]\n                if nearer:\n                    plan.append((source, nearer[0], int(have[source])))\n\n        # Only start-of-turn home units can deploy; returning units cannot\n        # be reused this turn. Every deployment is one legal link.\n        home_available = int(have[base])\n        for destination in sorted(desired):\n            deficit = max(0, desired[destination] - int(have[destination]))\n            count = min(home_available, deficit)\n            if count:\n                plan.append((base, destination, count))\n                home_available -= count\n\n        return legal_action(plan, have, adjacency)\n'
